def remplir(apps, schema_editor):
    """Taux de TVA du document : celui de ses lignes quand elles en ont un seul (taux mélangés : laissé vide, les
    lignes gardent le leur), ou pour un document sans ligne celui du régime fiscal du client. Marge des lignes de
    commande : celle de la ligne de devis d'origine, sinon la marge par défaut de l'article."""
    TauxTVA = apps.get_model("commercial", "TauxTVA")
    defaut = TauxTVA.objects.filter(est_defaut=True).first()
    zero = TauxTVA.objects.filter(taux=0).first()
    for nom in ("Devis", "Commande"):
        for document in apps.get_model("chiffrage", nom).objects.select_related("client"):
            taux = set(document.lignes.values_list("taux_tva_id", flat=True))
            if len(taux) > 1:
                continue
            if taux:
                document.taux_tva_id = taux.pop()
            else:
                regime_france = document.client.regime_fiscal == "france"
                document.taux_tva = defaut if regime_france else zero
            if document.taux_tva_id:
                document.save(update_fields=["taux_tva"])
    for ligne in apps.get_model("chiffrage", "CommandeLigne").objects.select_related("devis_ligne", "article"):
        marge = ligne.devis_ligne.taux_marge_matiere_applique if ligne.devis_ligne_id else None
        ligne.taux_marge = marge if marge is not None else ligne.article.taux_marge_defaut
        if ligne.taux_marge is not None:
            ligne.save(update_fields=["taux_marge"])


